    async fn score(&self, input: &ScoringInput) -> Result<ScoredPairs, EntityIngestionError> {
        let pairs = input
            .rows
            .iter()
            .enumerate()
            .flat_map(|(index, left)| {
                input.rows[index + 1..].iter().map(move |right| {
                    let (left, right) = if left.key < right.key {
